export const guides=[
{file:'brazil-pvc-wall-panels-picking-error-reconciliation.html',image:'november10-brazil.webp',product:'/products/pvc-wall-panels.html',catalog:'/assets/catalogs/dream-house-wall-panel-catalog.pdf',source:'https://support.gs1.org/support/solutions/articles/43000734475-how-does-traceability-work-',sourceName:'GS1: how traceability works',related:['brazil-pvc-wall-panels-stop-sale-batch-isolation.html'],en:{title:'Brazil PVC Panels: Reconcile Picking Errors | Luvie',heading:'Brazil PVC wall panels: reconcile a picking error without hiding the stock movement',description:'Resolve a PVC panel mispick by matching the order, shipped cartons, replacement and return records before correcting warehouse balances.',lead:'A Brazilian distributor receives a photograph showing that a customer ordered one PVC finish but received another. Sending the correct cartons may solve the immediate complaint, yet leave two incorrect stock balances and an unexplained invoice adjustment. A picking error needs a linked movement record, not simply an apology and a manual change to the inventory total. This guide proposes an internal reconciliation process for a commercial misdispatch; it does not assume a manufacturing defect or define local legal remedies.',answer:'Compare what was ordered, picked, dispatched and received using the original references and units. Control any replacement and return as separate linked movements, preserve the original transaction, and close the case only when physical quantities and authorized commercial adjustments agree. Do not make an unexplained stock adjustment to force the system to match.',sections:[['Establish which mismatch actually occurred','Ask for the order reference and readable photographs of the received carton labels, avoiding unnecessary customer personal data. Compare the approved order version with the pick ticket, dispatch record and customer evidence. Distinguish a wrong finish from a wrong quantity, a mislabeled carton or an unauthorized order substitution. If the contents and label disagree, record both observations and seek further inspection rather than assuming the picker caused it. State quantities in panels and cartons with the confirmed conversion between them. Preserve original scans and timestamps. Identify the smallest defensible set of related movements for review, while keeping uncertain items visible instead of declaring a cause prematurely.'],['Check the other side of the warehouse balance','Inspect the intended stock location and the location of the item apparently sent. A wrong pick can create a shortage in one reference and an apparent surplus in another. Check adjacent orders if the evidence suggests cartons may have been exchanged, but do not assume every nearby shipment is affected. GS1 describes traceability as connecting product data and recorded events during the physical flow of goods. That principle supports reconstruction of the movement; it does not automatically prove who made an error. Record counted quantities, counting time and any movements occurring during the count so later dispatches do not make the comparison misleading.'],['Link the remedy to separately identified movements','Agree the proposed remedy with the responsible account owner and customer under the applicable commercial process. If replacement cartons are authorized, create a traceable replacement instruction that references the original order and incident. Do not rewrite the original dispatch as though the correct goods had always been sent. If goods will return, identify the expected reference, quantity and return authorization separately. On receipt, inspect condition before restoring stock availability; a customer return is not automatically saleable. Ask the finance team to handle any credit, charge or corrected document through its authorized procedures. Keep logistics events and financial decisions linked but do not treat one as proof that the other is complete.'],['Close the incident with a reproducible reconciliation','Prepare a short closing table showing original dispatch, replacement dispatch, actual return, disposition and approved adjustments by reference and unit. Explain any quantity that remains outstanding rather than hiding it in a general variance. Have someone other than the original adjustment author review the evidence where practical. Test whether the remaining physical stock agrees with the recorded balance after the documented movements. Then address the demonstrated cause: clearer location labels, stronger reference confirmation or a controlled order-change handoff may be appropriate. Avoid adding burdensome checks unrelated to the evidence. Retain the incident link so a later return, invoice question or repeated complaint can be understood without reconstructing the case from messages.']],checklist:['Approved order and actual carton identities compared.','Both intended and incorrectly shipped stock locations reconciled.','Replacement, return and financial decisions recorded separately.','Closing quantities and any remaining discrepancy independently reviewed.'],faq:[['Should we delete the incorrect dispatch and enter the replacement?','Preserve the original history. Record the correction through the authorized workflow with linked replacement or return movements so the physical sequence remains understandable.'],['Can returned cartons go straight back into available stock?','Only after the applicable receiving and condition checks. Record the reference, quantity and disposition rather than assuming unopened-looking cartons are automatically suitable for resale.']],closing:'Send Luvie the PVC reference and relevant order or carton identifiers when requesting a shipment-record check. Describe the mismatch factually and keep the replacement, return and inventory decisions traceable.'}},
{file:'uae-wpc-wall-panels-mockup-signoff-responsibilities.html',image:'november10-uae.webp',product:'/products/wpc-wall-panels.html',catalog:'/assets/catalogs/wpc-collection-2026.pdf',source:'https://www.op.nysed.gov/professions/architecture/professional-practice/shop-drawings-submittals-and-delegation',sourceName:'New York State Education Department: submittal review guidance',related:['wall-panel-golden-sample-approval.html'],en:{title:'UAE WPC Panels: Mockup Signoff Responsibilities | Luvie',heading:'UAE WPC wall panels: define what each mockup signature approves',description:'Separate appearance, installation, interface and purchasing approvals for WPC mockups so one signature does not imply every project check is complete.',lead:'A WPC mockup may carry an approval signature while the purchasing team still does not know whether it can release the full order. The designer may have accepted the color only; the installer may still be waiting for a substrate decision; the project manager may assume both questions are settled. For a UAE interior project, a useful approval record identifies the question each reviewer answered and the conditions that remain open. It is not a collection of signatures with an undefined meaning.',answer:'Create a project-specific review matrix before the mockup is built. Assign reviewers for appearance, installation method, interfaces, required evidence and commercial release. Record each decision against the same identified mockup revision. Do not use aesthetic acceptance as a substitute for technical verification or a purchase authorization.',sections:[['Define the review questions and contractual authority','List what the mockup is intended to demonstrate: finish selection, joint appearance, workmanship, a specific junction or another agreed issue. For each question, identify the responsible reviewer under the project appointments and contracts. A suggested matrix is a coordination aid, not a change to contractual responsibility. New York State professional guidance distinguishes submittals and design review, but it is not UAE law and should not be imported as a local approval rule. Ask the UAE project team to confirm its own required reviewers and authority. Record who prepares the submission, who consolidates comments and who can authorize the next procurement or installation step.'],['Make every reviewer inspect the same configuration','Assign a mockup identifier and revision linked to the selected WPC reference, finish, supporting construction and relevant drawings. Identify accessory and fixing proposals without claiming their suitability before the responsible parties have reviewed them. Record the location and viewing conditions used for appearance review. If a component is changed after one reviewer signs, identify whether that change affects their earlier decision and obtain the necessary re-review. Photographs can support the record but should not replace an agreed physical inspection when the decision depends on texture or junction quality. Keep superseded versions available for history while clearly marking which configuration is current.'],['Use explicit statuses instead of an ambiguous approved stamp','Give each review item a result such as accepted for the stated purpose, accepted subject to listed conditions, revise and resubmit, or not reviewed. Define what those statuses allow within the project workflow. A condition should have an owner, a required response and a closure record; otherwise it can disappear between a meeting and the purchase order. Separate comments about appearance from questions about performance evidence or installation compatibility. Do not imply that a mockup proves fire, acoustic or other regulated performance merely because it looks satisfactory. Where the project requires independent evidence, keep that evidence as a separate review item with its own decision.'],['Release purchasing only after the relevant gates close','Before ordering the remaining quantity, compare the proposed order with the approved mockup reference and any closed conditions. Confirm which unresolved items prevent release and which, if any, the authorized project decision-maker has explicitly accepted for a limited next step. Record that limitation rather than describing the entire installation as approved. Preserve the accepted mockup or an agreed reference record for subsequent workmanship comparison. At handover, transfer the decision log to the people who will inspect the installed work. This avoids a later dispute in which one team treats a color signature as acceptance of every detail and another cannot identify the version that was actually reviewed.']],checklist:['Review questions and authorized reviewers agreed before fabrication.','All decisions linked to one identified mockup revision.','Conditions assigned owners and separately recorded closure.','Purchase release checked against reference and remaining restrictions.'],faq:[['Does the designer’s color approval authorize installation?','Not automatically. The record should state its purpose and the project’s separate technical, contractual and purchasing gates. Confirm authority through the actual project arrangements.'],['Must every change restart every review?','Assess which earlier decisions the change affects. Record the assessment and obtain the relevant re-approval instead of silently retaining signatures against a materially different configuration.']],closing:'Send Luvie the WPC reference and your mockup review questions. Request clearly identified product and packing information while your project team assigns the approval responsibilities and purchase-release decision.'}},
{file:'uzbekistan-pu-stone-panels-survey-datum-floor-level.html',image:'november10-uzbekistan.webp',product:'/products/pu-stone-panels.html',catalog:'/assets/catalogs/pu-stone-panel-catalog-en.pdf',source:'https://legacy.wbdg.org/do/functional/systems-integration',sourceName:'WBDG: product and systems integration',related:['uzbekistan-pu-stone-wall-panels-door-reveals.html'],en:{title:'Uzbekistan PU Panels: Survey Datum and Floor Level | Luvie',heading:'Uzbekistan PU stone panels: reconcile the survey datum before releasing quantities',description:'Coordinate wall measurements, finished-floor assumptions and drawing revisions before ordering PU stone panels for an Uzbekistan interior.',lead:'A wall height measured from the unfinished slab can differ from the height shown above the future finished floor. If those numbers enter the same PU stone-panel quantity sheet without explanation, the buyer may order to the wrong starting line or approve a layout that no longer meets the skirting and door details. For an Uzbekistan interior project, the practical task is to agree the measurement reference and resolve conflicting dimensions before the order is released, not to select a universal installation gap.',answer:'Use one documented project datum and distinguish existing measured surfaces from proposed finished surfaces. Link each wall dimension to its location, drawing revision and measurement basis. Have the responsible design and site teams resolve discrepancies before converting the approved elevation into panel quantities and cutting assumptions.',sections:[['State where every measurement starts and ends','Identify the wall by room and elevation, then record whether its height was measured from slab, existing floor or an established finished-floor reference. State the upper termination as well: visible ceiling, proposed ceiling line or another approved boundary. Keep units explicit and record the date and person who measured. A photograph of a tape can support a reading, but it rarely explains the whole reference system. Do not combine dimensions taken from different bases as if they described the same finished area. Where the finished level is not yet confirmed, mark the assumption and its owner rather than allowing a provisional number to look final.'],['Coordinate the adjacent finishes before freezing the elevation','Ask the project team to confirm the floor build-up, skirting approach, ceiling termination and relevant door or joinery interfaces. The WBDG systems-integration guidance emphasizes coordinating building elements and user requirements; it does not prescribe dimensions for a particular PU panel installation or establish Uzbekistan requirements. Treat it as a general coordination principle. The responsible professionals must determine the actual detail and any applicable constraints. Record which adjoining work is complete and which remains proposed. If an interface changes, compare the affected elevation and quantity assumptions rather than assuming the decorative panel can absorb every difference without a design decision.'],['Reconcile drawing and site differences visibly','Create a discrepancy list showing the drawing dimension, site reading, measurement basis and proposed resolution for each affected wall. Check whether an apparent conflict is simply a different reference level before requesting additional material. Do not average incompatible dimensions or silently replace a drawing value in a spreadsheet. Ask the authorized project reviewer to confirm the governing layout and document any revised termination or cut arrangement. Where a wall is irregular, request measurements sufficient for the actual layout rather than representing it with one convenient height. Keep surveying and technical design decisions with the competent project team; this purchasing guide does not authorize structural or building-service alterations.'],['Release a quantity sheet that preserves its assumptions','Convert only the agreed elevation into panel and accessory quantities using confirmed product dimensions and the selected layout. Identify full pieces, planned cuts and any agreed allowance separately so later readers can understand the calculation. Link the quantity sheet to the approved measurement record and drawing revision. Before issuing the purchase order, check whether a floor or ceiling change has occurred since the review. If final measurements are unavailable, obtain an explicit project decision about the remaining uncertainty rather than describing the quantity as verified. At installation handover, provide the approved starting line and references so the site team does not recreate the layout from an outdated quotation sketch.']],checklist:['Measurement datum, units and wall locations recorded.','Finished-floor and adjoining-finish assumptions assigned owners.','Drawing/site discrepancies resolved through a documented decision.','Quantity release linked to the approved elevation revision.'],faq:[['Can the unfinished slab height be used as the finished wall height?','Not without checking the intended floor and upper termination. Label the measurement basis and have the project team confirm the finished layout before calculating the final requirement.'],['Does this guide specify a standard bottom gap for PU panels?','No. The correct detail depends on the selected product and project interfaces. Obtain product-specific guidance and the responsible designer’s approved arrangement rather than copying a generic dimension.']],closing:'Send Luvie the PU stone-panel reference and an annotated wall elevation with its measurement basis. Confirm finished levels and termination details with your project team before asking for a quantity-based quotation.'}}
];
const ar=[
{title:'ألواح PVC في البرازيل: تسوية أخطاء تجهيز الطلب | Luvie',heading:'ألواح PVC في البرازيل: سوِّ خطأ تجهيز الطلب دون إخفاء حركة المخزون',description:'عالج شحن ألواح PVC الخاطئة بمطابقة الطلب والعبوات المشحونة والبديل والمرتجع قبل تصحيح أرصدة المستودع.',lead:'يتلقى موزع برازيلي صورة تبين أن العميل طلب تشطيب PVC واستلم آخر. قد يحل إرسال العبوات الصحيحة الشكوى المباشرة، لكنه يترك رصيدين خاطئين وتعديلاً غير مفسر في الفاتورة. يحتاج خطأ التجهيز إلى سجل حركات مترابط، وليس اعتذاراً وتغييراً يدوياً للإجمالي فقط. يقترح الدليل تسوية داخلية لشحن تجاري خاطئ؛ ولا يفترض عيب تصنيع أو يحدد وسائل المعالجة القانونية المحلية.',answer:'قارن المطلوب والمجهز والمشحون والمستلم بالمراجع والوحدات الأصلية. سجل البديل والمرتجع كحركتين مستقلتين مترابطتين واحفظ المعاملة الأصلية، ولا تغلق الحالة قبل توافق الكميات الفعلية والتعديلات التجارية المعتمدة. لا تستخدم تعديلاً مجهول السبب لإجبار النظام على المطابقة.',sections:[['حدد نوع الاختلاف الفعلي','اطلب مرجع الطلب وصوراً مقروءة لملصقات العبوات المستلمة، دون بيانات شخصية غير لازمة. قارن نسخة الطلب المعتمدة بتذكرة التجهيز وسجل الشحن وأدلة العميل. ميز التشطيب الخاطئ عن الكمية الخاطئة والملصق غير الصحيح وتغيير الطلب غير المصرح به. إذا اختلف المحتوى عن الملصق، فسجل الملاحظتين واطلب فحصاً إضافياً بدلاً من افتراض خطأ العامل. اذكر الكميات بالألواح والعبوات مع التحويل المؤكد بينهما. احفظ المسوح والتوقيتات الأصلية. حدد أصغر مجموعة حركات تدعم الأدلة مراجعتها، وأبق العناصر غير المؤكدة ظاهرة بدلاً من إعلان السبب مبكراً.'],['افحص الطرف الآخر من رصيد المستودع','افحص موقع الصنف المطلوب وموقع الصنف الذي يبدو أنه شُحن. قد يخلق التجهيز الخاطئ نقصاً في مرجع وفائضاً ظاهرياً في آخر. راجع الطلبات المجاورة إذا أشارت الأدلة إلى تبادل العبوات، لكن لا تفترض تأثر كل الشحنات القريبة. تصف GS1 التتبع بربط بيانات المنتج والأحداث المسجلة أثناء التدفق المادي للبضائع. يساعد هذا المبدأ على إعادة بناء الحركة، لكنه لا يثبت تلقائياً من أخطأ. سجل الكميات المعدودة ووقت العد وأي حركات حدثت أثناءه كي لا تجعل الشحنات اللاحقة المقارنة مضللة.'],['اربط المعالجة بحركات محددة مستقلة','اتفق على المعالجة المقترحة مع مسؤول الحساب والعميل وفق الإجراء التجاري المطبق. إذا اعتُمد إرسال بديل، فأنشئ تعليمات قابلة للتتبع تشير للطلب الأصلي والحادث. لا تعد كتابة الشحنة الأصلية كأن البضاعة الصحيحة أُرسلت منذ البداية. إذا ستعود بضاعة، فحدد المرجع والكمية المتوقعة وإذن الإرجاع منفصلين. افحص الحالة عند الاستلام قبل إتاحة المخزون؛ فالمرتجع ليس صالحاً للبيع تلقائياً. دع الفريق المالي يعالج أي إشعار دائن أو رسم أو مستند مصحح عبر إجراءاته المعتمدة. اربط أحداث النقل والقرارات المالية دون اعتبار اكتمال أحدها دليلاً على اكتمال الآخر.'],['أغلق الحالة بتسوية يمكن إعادة فحصها','أعد جدول إغلاق يبين الشحنة الأصلية وشحنة البديل والمرتجع الفعلي والتصرف والتعديلات المعتمدة حسب المرجع والوحدة. فسر الكمية المعلقة بدلاً من إخفائها في فرق عام. اطلب مراجعة الأدلة من شخص غير منشئ التعديل حيث أمكن. اختبر توافق المخزون الفعلي المتبقي مع الرصيد المسجل بعد الحركات الموثقة. ثم عالج السبب المثبت: قد تلزم ملصقات مواقع أوضح أو تأكيد أقوى للمرجع أو تسليم منظم لتغييرات الطلب. تجنب إضافة فحوص مرهقة لا ترتبط بالأدلة. احفظ رابط الحادث لفهم أي مرتجع أو استفسار فاتورة أو شكوى متكررة لاحقاً دون إعادة تجميع الرسائل.']],checklist:['مقارنة الطلب المعتمد بهوية العبوات الفعلية.','تسوية موقعي الصنف المطلوب والصنف المشحون خطأً.','تسجيل البديل والمرتجع والقرارات المالية منفصلة.','مراجعة كميات الإغلاق والفرق المتبقي بصورة مستقلة.'],faq:[['هل نحذف الشحنة الخاطئة وندخل البديل؟','احفظ التاريخ الأصلي وسجل التصحيح عبر المسار المعتمد مع ربط حركات البديل أو المرتجع حتى يبقى تسلسل الوقائع واضحاً.'],['هل تعود العبوات المرتجعة مباشرة للمخزون المتاح؟','فقط بعد فحوص الاستلام والحالة المطبقة. سجل المرجع والكمية والتصرف، ولا تفترض صلاحية إعادة البيع من مظهر العبوة المغلقة.']],closing:'أرسل إلى Luvie مرجع PVC ومعرفات الطلب أو العبوات عند طلب فحص سجل الشحنة. صف الاختلاف واقعياً واجعل قرارات البديل والمرتجع والمخزون قابلة للتتبع.'},
{title:'ألواح WPC للإمارات: مسؤوليات اعتماد النموذج | Luvie',heading:'ألواح WPC للإمارات: حدد ما يعتمده كل توقيع على النموذج',description:'افصل موافقات المظهر والتركيب والوصلات والشراء كي لا يعني توقيع واحد اكتمال جميع فحوص المشروع.',lead:'قد يحمل نموذج WPC توقيع اعتماد بينما لا يعرف فريق المشتريات إن كان يستطيع إصدار الطلب الكامل. ربما اعتمد المصمم اللون فقط، وما زال المركّب ينتظر قرار السطح الحامل، بينما يظن مدير المشروع حسم الأمرين. في مشروع داخلي بالإمارات، يحدد السجل المفيد السؤال الذي أجاب عنه كل مراجع والشروط المفتوحة. ليس مجرد مجموعة توقيعات مجهولة المعنى.',answer:'أنشئ مصفوفة مراجعة خاصة بالمشروع قبل بناء النموذج. عين مراجعين للمظهر وطريقة التركيب والتقاطعات والأدلة المطلوبة والإفراج التجاري. سجل كل قرار مقابل النسخة المحددة نفسها. لا تستخدم قبول المظهر بديلاً للتحقق الفني أو إذن الشراء.',sections:[['حدد أسئلة المراجعة والصلاحيات التعاقدية','اكتب ما يراد للنموذج إثباته: اختيار التشطيب أو مظهر الفواصل أو جودة التنفيذ أو تقاطع محدد أو مسألة متفق عليها. حدد مراجع كل سؤال وفق تعيينات المشروع وعقوده. المصفوفة المقترحة أداة تنسيق وليست تعديلاً للمسؤولية التعاقدية. تميز إرشادات ولاية نيويورك المهنية بين المستندات المقدمة ومراجعة التصميم، لكنها ليست قانوناً إماراتياً ولا تُنقل كقاعدة اعتماد محلية. اطلب من فريق المشروع الإماراتي تأكيد مراجعيه وصلاحياتهم. سجل من يُعد التقديم ومن يجمع التعليقات ومن يأذن بالخطوة التالية للشراء أو التركيب.'],['اجعل الجميع يراجعون التكوين نفسه','عين معرفاً ورقم مراجعة للنموذج يرتبطان بمرجع WPC والتشطيب والبناء الحامل والرسومات ذات الصلة. حدد الإكسسوارات والتثبيت المقترحين دون ادعاء ملاءمتهما قبل مراجعة المسؤولين. سجل موقع وظروف مشاهدة المظهر. إذا تغير مكون بعد توقيع مراجع، فحدد أثره على قراره السابق واطلب إعادة المراجعة اللازمة. تدعم الصور السجل لكنها لا تستبدل فحصاً فعلياً متفقاً عليه عندما يعتمد القرار على الملمس أو جودة الوصلة. احتفظ بالنسخ السابقة للتاريخ مع تمييز التكوين الحالي بوضوح.'],['استخدم حالات صريحة لا ختم موافقة غامضاً','امنح كل بند نتيجة مثل مقبول للغرض المحدد أو مقبول بشروط مدونة أو يُراجع ويعاد تقديمه أو لم يُراجع. عرّف ما تسمح به الحالات في مسار المشروع. يجب أن يكون لكل شرط مسؤول ورد مطلوب وسجل إغلاق، وإلا قد يضيع بين الاجتماع وأمر الشراء. افصل تعليقات المظهر عن أسئلة أدلة الأداء أو توافق التركيب. لا توحِ بأن النموذج يثبت أداء الحريق أو الصوت أو غيره من الأداء المنظم لمجرد رضى المراجعين عن شكله. عندما تلزم أدلة مستقلة، اجعلها بند مراجعة مستقلاً بقراره الخاص.'],['أفرج عن الشراء بعد إغلاق الشروط اللازمة','قبل طلب الكمية المتبقية، قارن الطلب المقترح بمرجع النموذج المعتمد والشروط المغلقة. أكد أي المسائل المفتوحة يمنع الإفراج وأيها، إن وجد، قبله صاحب القرار المخول صراحة لخطوة تالية محدودة. سجل الحد بدلاً من وصف التركيب كله بأنه معتمد. احفظ النموذج المقبول أو مرجعاً متفقاً عليه لمقارنة جودة التنفيذ لاحقاً. عند التسليم انقل سجل القرارات لمن سيفحص العمل المنفذ. يمنع ذلك نزاعاً يعتبر فيه فريق توقيع اللون قبولاً لكل تفصيل، بينما يعجز آخر عن تحديد النسخة التي تمت مراجعتها فعلاً.']],checklist:['الاتفاق على الأسئلة والمراجعين المخولين قبل التصنيع.','ربط جميع القرارات بنسخة نموذج محددة واحدة.','تعيين أصحاب الشروط وتوثيق إغلاقها منفصلاً.','فحص الإفراج عن الشراء مقابل المرجع والقيود المتبقية.'],faq:[['هل موافقة المصمم على اللون تأذن بالتركيب؟','ليس تلقائياً. يجب أن يحدد السجل الغرض ومتطلبات المشروع الفنية والتعاقدية والتجارية المنفصلة. أكد الصلاحية وفق ترتيبات المشروع الفعلية.'],['هل يعيد كل تغيير جميع المراجعات؟','قيّم القرارات السابقة التي يؤثر فيها التغيير، وسجل التقييم واحصل على الاعتماد اللازم بدلاً من إبقاء التوقيعات بصمت على تكوين مختلف جوهرياً.']],closing:'أرسل إلى Luvie مرجع WPC وأسئلة مراجعة النموذج. اطلب معلومات منتج وتعبئة محددة الهوية بينما يحدد فريق المشروع مسؤوليات الاعتماد وقرار الإفراج عن الشراء.'},
{title:'ألواح PU لأوزبكستان: مرجع القياس ومنسوب الأرضية | Luvie',heading:'ألواح PU الحجرية لأوزبكستان: طابق مرجع القياس قبل اعتماد الكميات',description:'نسّق قياسات الجدار وافتراضات الأرضية النهائية ومراجعات الرسومات قبل طلب ألواح PU لمشروع أوزبكستان.',lead:'قد يختلف ارتفاع الجدار المقاس من البلاطة غير المشطبة عن الارتفاع فوق الأرضية النهائية المستقبلية. إذا دخل الرقمان ورقة كميات ألواح PU دون تفسير، فقد يطلب المشتري على أساس خط بداية خاطئ أو يعتمد توزيعاً لا يوافق الوزرة وتفاصيل الباب. في مشروع داخلي بأوزبكستان، المطلوب الاتفاق على مرجع القياس وحل تضارب الأبعاد قبل إصدار الطلب، وليس اختيار فجوة تركيب موحدة.',answer:'استخدم منسوباً مرجعياً واحداً موثقاً للمشروع وميز الأسطح الحالية المقاسة عن الأسطح النهائية المقترحة. اربط كل بُعد بموقعه ومراجعة الرسم وأساس القياس. دع فريقي التصميم والموقع المسؤولين يحلان الفروق قبل تحويل الواجهة المعتمدة إلى كميات وافتراضات قص.',sections:[['وضح بداية كل قياس ونهايته','عرّف الجدار بالغرفة والواجهة، وسجل هل قيس ارتفاعه من البلاطة أو الأرضية الحالية أو مرجع منسوب التشطيب المحدد. حدد النهاية العليا أيضاً: السقف المرئي أو خط السقف المقترح أو حد معتمد آخر. وضح الوحدات وتاريخ القياس والقائم به. قد تدعم صورة شريط القياس القراءة لكنها نادراً ما تشرح النظام المرجعي كله. لا تجمع أبعاداً من قواعد مختلفة وكأنها تصف مساحة نهائية واحدة. إذا لم يُؤكد المنسوب النهائي، فبيّن الافتراض والمسؤول عنه بدلاً من إظهار الرقم المؤقت كأنه نهائي.'],['نسّق التشطيبات المجاورة قبل تثبيت الواجهة','اطلب من فريق المشروع تأكيد طبقات الأرضية وطريقة الوزرة ونهاية السقف وتقاطعات الأبواب أو النجارة. تؤكد إرشادات تكامل الأنظمة في WBDG تنسيق عناصر المبنى واحتياجات المستخدم؛ لكنها لا تفرض أبعاداً لتركيب PU معين ولا تحدد متطلبات أوزبكستان. استخدمها كمبدأ تنسيق عام. على المختصين المسؤولين تحديد التفصيل الفعلي والقيود المطبقة. سجل أي الأعمال المجاورة مكتمل وأيها مقترح. إذا تغير تقاطع، فراجع الواجهة وافتراضات الكمية المتأثرة بدلاً من افتراض أن اللوح الزخرفي يستوعب كل فرق دون قرار تصميم.'],['أظهر تسوية اختلاف الرسم والموقع','أنشئ قائمة فروق تبين بُعد الرسم وقراءة الموقع وأساس القياس والحل المقترح لكل جدار متأثر. تحقق هل التعارض الظاهر مجرد اختلاف منسوب مرجعي قبل طلب مواد إضافية. لا تأخذ متوسط أبعاد غير متوافقة ولا تستبدل قيمة الرسم بصمت في جدول. اطلب من المراجع المخول تأكيد التوزيع الحاكم وتوثيق أي تعديل للنهاية أو ترتيب القص. إذا كان الجدار غير منتظم، فاطلب قياسات كافية للتوزيع الفعلي بدلاً من تمثيله بارتفاع واحد مريح. اترك القياس والقرارات الفنية للفريق المختص؛ دليل الشراء لا يأذن بتعديلات إنشائية أو خدمات مبنى.'],['اعتمد ورقة كميات تحفظ افتراضاتها','حوّل الواجهة المتفق عليها فقط إلى كميات ألواح وإكسسوارات وفق أبعاد المنتج المؤكدة والتوزيع المختار. افصل القطع الكاملة والقص المخطط والسماحية المتفق عليها لفهم الحساب لاحقاً. اربط ورقة الكميات بسجل القياس ومراجعة الرسم المعتمدين. قبل أمر الشراء تحقق من أي تغيير في الأرضية أو السقف بعد المراجعة. إذا غابت القياسات النهائية، فاحصل على قرار صريح بشأن عدم اليقين المتبقي بدلاً من وصف الكمية بأنها متحققة. عند تسليم التركيب قدم خط البداية والمراجع المعتمدة كي لا يعيد فريق الموقع التوزيع من رسم عرض سعر قديم.']],checklist:['تسجيل مرجع القياس والوحدات ومواقع الجدران.','تعيين مسؤولي افتراضات الأرضية والتشطيبات المجاورة.','حل فروق الرسم والموقع بقرار موثق.','ربط اعتماد الكميات بمراجعة الواجهة المعتمدة.'],faq:[['هل يمكن اعتماد ارتفاع البلاطة غير المشطبة كارتفاع الجدار النهائي؟','ليس دون فحص الأرضية المقصودة والنهاية العليا. وضح أساس القياس ودع فريق المشروع يؤكد التوزيع النهائي قبل حساب الاحتياج.'],['هل يحدد الدليل فجوة سفلية قياسية لألواح PU؟','لا. يعتمد التفصيل على المنتج والتقاطعات. اطلب إرشادات المنتج وترتيب المصمم المعتمد بدلاً من نسخ بُعد عام.']],closing:'أرسل إلى Luvie مرجع ألواح PU وواجهة جدار مشروحة بأساس القياس. أكد المناسيب النهائية وتفاصيل النهايات مع فريق المشروع قبل طلب عرض قائم على الكميات.'}
];
guides.forEach((guide,index)=>{guide.ar=ar[index];});
const translations = JSON.parse((await import('node:fs')).readFileSync(new URL('./daily-guides-20261110-es-pt.json', import.meta.url), 'utf8'));
for (const guide of guides) Object.assign(guide, translations[guide.file]);
